refentry.refsect1:
  &reftitle.examples;

   Esempio di untaint


<?php
$id = "42";
taint($id);
if (preg_match('/^\d+$/', $id)) {
    // validato rigorosamente come cifre: è sicuro fidarsi
    untaint($id);
}
var_dump(is_tainted($id));
?>


   &example.outputs.similar;


bool(false)

&reftitle.notes;


  Solo i valori stringa possono portare il contrassegno; passare un valore non stringa non
  ha alcun effetto.
